/* ---- API сервера проекта (если он запущен) ---- */
const API=location.protocol==='file:'?'http://localhost:8000':'';
async function api(path,body,timeout=15000){const c=new AbortController(),t=setTimeout(()=>c.abort(),timeout);
  const hd={};if(body)hd['Content-Type']='application/json';if(/^\/api\/(auth|me|history|progress|export)/.test(path))hd['X-CS']='1';
  try{const r=await fetch(API+path,{method:body?'POST':'GET',headers:hd,body:body?JSON.stringify(body):undefined,signal:c.signal});
    return{ok:r.ok,status:r.status,data:await r.json().catch(()=>({}))}}catch(e){return null}finally{clearTimeout(t)}}
let svc;
function renderStatus(){const e=$('svcStatus');if(!e)return;e.innerHTML='';if(svc===undefined)return;
  if(svc===false){e.append(h('span','chip off',x('Сервер проекта недоступен: работают только проверки в браузере. Запустите server.py (см. README).')));return}
  [['Google Safe Browsing',svc.safebrowsing],[x('База жалоб'),svc.reports],['VirusTotal',svc.virustotal]].forEach(([n,on])=>e.append(h('span','chip '+(on?'on':'off'),n+': '+(on?x('подключено'):x('не подключено')))));
  if(me===null&&location.protocol!=='file:'){const l=h('a','chip off',x('Войдите, чтобы сохранять историю проверок'));l.href='account.html';e.append(l)}}
async function loadStatus(){if(!$('svcStatus'))return;const r=await api('/api/status',null,5000);svc=r&&r.ok?r.data:false;renderStatus()}

/* ---- перевод статического текста ---- */
const orig=new Map();
function translatePage(){
  const w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode:n=>(!n.nodeValue.trim()||n.parentElement.closest('script,style,[data-skip],.result'))?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});
  let n;while(n=w.nextNode()){if(!orig.has(n))orig.set(n,n.nodeValue);const o=orig.get(n),k=o.trim(),t=tr(k);n.nodeValue=t===k?o:o.replace(k,()=>t)}
  document.querySelectorAll('[placeholder],[aria-label],[title],meta[name=description]').forEach(el=>{
    if(el.id==='urlInput'||el.closest('[data-skip]'))return;el._o=el._o||{};
    ['placeholder','aria-label','title','content'].forEach(a=>{if(!el.hasAttribute(a))return;if(el._o[a]===undefined)el._o[a]=el.getAttribute(a);el.setAttribute(a,tr(el._o[a]))})});
  if(root._t===undefined)root._t=document.title;
  const p=root._t.split(' | ');document.title=tr(p[0])+' | '+p.slice(1).join(' | ');
}
function clearResult(r){r._s=(r._s||0)+1;r.className='result';r.innerHTML=''}
function setLang(l){
  lang=l;root.lang=l;try{localStorage.setItem('cs-lang',l)}catch(e){}
  if(sel)sel.value=l;translatePage();
  document.querySelectorAll('.result').forEach(clearResult);
  const rf=$('reportForm');if(rf){rf.hidden=true;$('reportMsg').textContent=''}lastPhone=null;
  renderStatus();acRender();ckRender();hooks.forEach(f=>f());if(setTab)setTab(curTab);
}
['change','input'].forEach(ev=>{if(sel)sel.addEventListener(ev,()=>{if(sel.value!==lang)setLang(sel.value)})});

