/* ---- ситуация (страница «Защита») ---- */
const sf=$('situationForm');
if(sf){
  sf.addEventListener('submit',e=>{e.preventDefault();
    const k=$('situation').value,w=[...document.querySelectorAll('[name=warning]:checked')].map(v=>v.value),o=$('situationResult');
    if(!k)return show(o,'medium',tr('Выберите ситуацию'),'<p>'+m('chooseP')+'</p>');
    let level='low',title=m('lowT'),advice=m('lowA');
    if(w.includes('code')||w.includes('money')||w.length>=3){level='high';title=m('highT');advice=m('highA')}
    else if(w.length||['account','payment','offer'].includes(k)){level='medium';title=m('medT');advice=m('medA')}
    show(o,level,title,'<p><strong>'+m('selected')+'</strong> '+m(k)+'.</p><p>'+advice+'</p><p>'+m('sitEnd')+'</p>')});
  sf.addEventListener('reset',()=>clearResult($('situationResult')));
}

/* ---- ссылки ---- */
function parseUrl(raw){let v=raw.trim();
  if(!v)throw Error('eEmpty');if(/\s/.test(v))throw Error('eSpace');
  if(!/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\//.test(v))v='https://'+v;
  let u;try{u=new URL(v)}catch(e){throw Error('eBad')}
  if(!['http:','https:'].includes(u.protocol))throw Error('eProto');
  if(!u.hostname||!u.hostname.includes('.'))throw Error('eDomain');return u}
