const BADTLD=['tk','ml','ga','cf','gq','xyz','top','click','icu','buzz'];
const SAFE_LINK=['kaspi.kz','halykbank.kz','egov.kz','gov.kz'];
const SHORT=['bit.ly','tinyurl.com','cutt.ly','t.ly','clck.ru','goo.gl','is.gd','rb.gy','ow.ly','vk.cc','shorturl.at','tiny.cc','s.id'];
const norm=(s,one)=>s.replace(/0/g,'o').replace(/1/g,one).replace(/3/g,'e').replace(/5/g,'s').replace(/rn/g,'m').replace(/vv/g,'w').replace(/[-.]/g,'');
function analyzeUrl(u){const hn=u.hostname.toLowerCase(),f=[],lb=hn.split('.');
  if(u.protocol!=='https:')f.push(m('fHttp'));
  if(u.username||u.password)f.push(m('fAt'));
  if(hn.startsWith('xn--')||hn.includes('.xn--'))f.push(m('fPuny'));
  if(/^\d{1,3}(\.\d{1,3}){3}$/.test(hn))f.push(m('fIp'));
  if((hn.match(/-/g)||[]).length>=3)f.push(m('fHy'));
  if(lb.some(v=>v.length>30))f.push(m('fLong'));
  if(lb.length>=5)f.push(m('fSub'));
  if(BADTLD.includes(lb[lb.length-1]))f.push(m('fTld',lb[lb.length-1]));
  const official=OFF.some(d=>hn===d||hn.endsWith('.'+d)),n1=norm(hn,'l'),n2=norm(hn,'i'),b=BR.find(v=>n1.includes(v)||n2.includes(v));
  if(b&&!official)f.push(m('fBrand',b));
  if(/(login|verify|secure|account|wallet|update|password|payment)/i.test(hn))f.push(m('fKw'));
  return f}
const TN={MALWARE:'вредоносное ПО',SOCIAL_ENGINEERING:'фишинг или обман',UNWANTED_SOFTWARE:'нежелательное ПО',POTENTIALLY_HARMFUL_APPLICATION:'потенциально опасное приложение'};
function repOf(res){const L=[];let threat=false;
  if(res&&res.status===429)return{L:[x('Слишком много проверок подряд. Повторите через минуту.')],threat};
  if(!res||!res.ok)return{L:[x('Онлайн-сверка с базами угроз недоступна.')],threat};
  const d=res.data,sb=d.safebrowsing||{},vt=d.virustotal||{};
  if(sb.status==='threat'){threat=true;L.push(x('Google Safe Browsing: адрес числится в базе угроз ({0}).',(sb.types||[]).map(t=>x(TN[t]||'')||t).join(', ')))}
  else L.push(sb.status==='clean'?x('Google Safe Browsing: угроз не найдено.'):sb.status==='off'?x('Google Safe Browsing: не подключён на сервере.'):x('Google Safe Browsing: не удалось получить ответ.'));
  if(vt.status==='threat'){threat=true;L.push(x('VirusTotal: {0} из {1} движков считают адрес вредоносным или подозрительным.',vt.flagged,vt.total))}
  else L.push(vt.status==='clean'?x('VirusTotal: вредоносным адрес не признан ({0} движков проверили).',vt.total):vt.status==='queued'?x('VirusTotal: адрес отправлен на анализ. Повторите проверку через минуту.'):vt.status==='off'?x('VirusTotal: не подключён на сервере.'):x('VirusTotal: не удалось получить ответ (возможен лимит запросов).'));
  return{L,threat}}

async function runUrl(raw,o,kind){
  let u;try{u=parseUrl(raw)}catch(err){return show(o,'medium',m('urlFixT'),'<p>'+m(err.message)+'</p><p>'+m('urlFixP')+'</p>')}
  const f=analyzeUrl(u);clearResult(o);const seq=o._s;
  const render=rp=>{const threat=rp&&rp.threat,kindc=threat?'high':f.length?'medium':'info',title=threat?x('Адрес числится в базах угроз'):f.length?m('urlWarnT'):m('urlOkT');
    const a=h('span','address',u.href),pa=h('p');pa.append(h('strong','',m('addr')+' '),a);
    const nodes=[pa];if(f.length)nodes.push(ul(f));else if(!threat)nodes.push(h('p','',m('urlNone').replace(/<\/?strong>/g,'')));
    nodes.push(rp?(rp.L.length?ul(rp.L):h('p')):h('p','muted',x('Проверяем по базам угроз…')));
    nodes.push(h('p','',threat?x('Не открывайте эту ссылку и не вводите данные. Если вы уже перешли по ней, смените пароли и свяжитесь с банком.'):m('urlEnd')));
    nodes.push(h('p','disclaimer',m('urlDisc')));paint(o,kindc,title,nodes);return kindc};
  render(null);o.focus();
  const res=await api('/api/url',{url:u.href});if(o._s!==seq)return;const rp=repOf(res);logCheck(kind,render(rp),u.hostname)}
const uf=$('urlForm');
if(uf)uf.addEventListener('submit',e=>{e.preventDefault();runUrl($('urlInput').value,$('urlResult'),'url')});

/* ---- SMS ---- */
const URLRE=/(?:https?:\/\/|www\.)[^\s<>"'()]+|[a-z0-9][a-z0-9-]*(?:\.[a-z0-9-]+)*\.(?:com|kz|ru|org|net|info|xyz|top|click|me|ly|cc|io|site|online|app|link|cn|tk|ml|ga|cf|gq|icu|buzz|su|by|uz|kg|ua|co|to|in|vip|shop|store|club|live)(?:\/[^\s<>"'()]*)?/gi;
function extractLinks(t){const out=[];for(const mt of t.matchAll(URLRE)){if(t[mt.index-1]==='@')continue;const s=mt[0].replace(/[.,;:!?»”]+$/,'');if(s&&!out.includes(s))out.push(s)}return out.slice(0,5)}
const VERBS=new Set(['сообщите','сообщи','назовите','назови','продиктуйте','пришлите','пришли','отправьте','отправь','скажите','введите','перешлите','подтвердите','айтыңыз','жіберіңіз','енгізіңіз','хабарлаңыз','send','tell','share','give','provide','enter','reply','read']);
const NEG=/(никому не|не сообщайте|не называйте|не говорите|не передавайте|не сообщать|ешкімге айтпаңыз|ешкімге бермеңіз|ешкімге жібермеңіз|do not share|don't share|never share|not share|do not tell)/i,EXCEPT=/(кроме|except|за исключением)/i;
function asksSecret(t){const w=t.split(/\s+/).map(s=>s.replace(/[^\p{L}\p{N}'-]/gu,''));
  for(let i=0;i<w.length;i++)if(VERBS.has(w[i]))for(let j=Math.max(0,i-4);j<=Math.min(w.length-1,i+5);j++)if(j!==i&&/^(код|пин|pin|cvv|cvc|парол|құпиясөз|otp|password|code)/.test(w[j]))return true;return false}
const RULES=[
 ['Давит срочностью или угрозой блокировки.',15,/(срочн|немедленн|незамедлительн|в течение\s+\d+\s*(час|мин|сут)|последн[а-я]+ (предупрежд|уведомл)|заблокир|блокиров|приостановл|аннулир|будет закрыт|штраф|задолженност|шұғыл|дереу|бұғатта|тоқтатыл|айыппұл|берешек|urgent|immediately|within \d+\s*(hour|minute|day)|final (warning|notice)|blocked|suspended|will be closed|penalty|overdue)/i],
 ['Обещает приз, выплату, компенсацию или одобренный кредит.',20,/(выигр|приз\b|призов|подарок|розыгрыш|компенсац|выплат[аыу]|одобрен[а-я]* (кредит|заявк)|бонус|кэшбэк|лотере|возврат средств|возврат налог|ұтыс|ұтып|сыйлық|өтемақы|you (have )?won|prize|reward|lottery|compensation|refund|gift)/i],
 ['Предлагает быстрый заработок или инвестиции.',15,/(инвестиц|заработок|подработк|пассивн|крипт|биткоин|форекс|без вложений|удал[её]нн[а-я]+ работ|работа на дому|трейд|табыс|қосымша жұмыс|қашықтан жұмыс|invest|earn \$?\d|passive income|bitcoin|forex|work from home|trading)/i],
 ['Просит установить приложение или дать удалённый доступ.',30,/(установ[иы][а-я]* (приложени|программ)|скача[йт][а-я]*\s+(приложени|apk|программ)|\.apk\b|anydesk|teamviewer|rustdesk|удал[её]нн[а-я]+ доступ|қосымшаны орнат|қашықтан қолжетімділік|install (the )?app|download (the )?(app|apk)|remote access)/i,1],
 ['Требует перевести деньги или назвать «безопасный счёт».',30,/(переведите|перечислите|оплатите|внесите|безопасн[а-я]+ сч[её]т|резервн[а-я]+ сч[её]т|депозит|залог|предоплат|комисси[яю] за|аударыңыз|төлеңіз|қауіпсіз шот|алдын ала төлем|transfer (the )?(money|funds)|wire |pay (a )?(fee|deposit)|safe account|advance payment|processing fee)/i,1],
 ['Просит личные или карточные данные.',20,/(\bиин\b|паспорт|номер карты|номер сч[её]та|срок действия карты|жеке куәлік|\bжсн\b|карта нөмірі|passport|card number|date of birth)/i],
 ['Зовёт продолжить общение в мессенджере или по телефону.',8,/(whatsapp|ватсап|вотсап|telegram|телеграм|свяжитесь|позвоните|напишите нам|байланысыңыз|қоңырау шалыңыз|contact us|call us|message us)/i]];
const ORG=/(kaspi|каспи|halyk|халык|jusan|жусан|forte|egov|налогов|полици|прокуратур|казпочт|kazpost|нацбанк|банк|\bмвд\b|\bкнб\b|bank|police)/i;
function scoreSms(text){
  const t=text.toLowerCase(),links=extractLinks(text),R=[],lk=[];let s=0,strong=0;
  const add=(w,ru,...a)=>{s+=w;R.push([w,x(ru,...a)])};
  const neg=NEG.test(t)&&!EXCEPT.test(t);
  if(!neg&&asksSecret(t)){add(35,'Просит назвать, ввести или переслать код, PIN или пароль.');strong++}
  RULES.forEach(([k,w,re,st])=>{if(re.test(t)){add(w,k);if(st)strong++}});
  const parsed=links.map(l=>{let u=null;try{u=parseUrl(l)}catch(e){}return u}).filter(Boolean).filter(u=>{const hn=u.hostname.toLowerCase();return!SAFE_LINK.some(d=>hn===d||hn.endsWith('.'+d))});
  if(parsed.length)add(12,'В сообщении есть ссылка.');
  let bad=0;
  parsed.forEach(u=>{lk.push({href:u.href});const hn=u.hostname.toLowerCase();
    if(SHORT.some(d=>hn===d)){add(20,'Ссылка сокращена, настоящий адрес скрыт.')}
    const f=analyzeUrl(u);if(f.length&&bad<2){bad++;add(15,'Подозрительная ссылка {0}: {1}',hn,f[0])}});
  if(!neg&&asksSecret(t)&&(parsed.length||RULES[0][2].test(t)))s+=10;
  if(s>0&&ORG.test(t))add(5,'Упоминает банк или госорган, под которые часто маскируются мошенники.');
  if(strong&&s<20)s=20;
  s=Math.min(100,s);
  const otp=neg&&/\b\d{4,8}\b/.test(t)&&!parsed.length&&strong===0&&R.every(r=>r[0]<=8||r[0]===5);
  const level=otp?'info':s<20?'low':s<45?'medium':'high';
  R.sort((a,b)=>b[0]-a[0]);return{s,level,R:R.map(r=>r[1]),lk:lk.slice(0,3),otp}}
const sm=$('smsForm');
if(sm)sm.addEventListener('submit',async e=>{e.preventDefault();
  const o=$('smsResult'),text=$('smsInput').value.trim();
  if(!text)return show(o,'medium',x('Вставьте текст сообщения.'),'');
  const r=scoreSms(text);clearResult(o);const seq=o._s;
  const T={info:x('Похоже на одноразовый код'),low:x('Явных признаков мошенничества не найдено'),medium:x('Есть тревожные признаки'),high:x('Высокая вероятность мошенничества')};
  const A={info:x('Одноразовый код нельзя сообщать никому, в том числе «сотруднику банка» или «службе безопасности». Если вы не запрашивали код, кто-то пытается войти в ваш аккаунт: смените пароль.'),low:x('Это не гарантия безопасности. Если сообщение просит что-то сделать, проверьте отправителя через официальное приложение или номер организации.'),medium:x('Не торопитесь: не переходите по ссылкам и не называйте коды. Проверьте отправителя через официальное приложение или номер, найденный самостоятельно.'),high:x('Не переходите по ссылкам, не называйте коды и не переводите деньги. Если вы уже что-то сделали, срочно позвоните в банк по официальному номеру.')};
  let level=r.level,reasons=r.R.slice();const meter=h('div','meter'),bar=h('span');bar.style.width=r.s+'%';meter.append(bar);meter.setAttribute('role','img');meter.setAttribute('aria-label',x('Оценка риска: {0} из 100',r.s));
  const linkUl=h('ul','links'),rep=new Map();
  r.lk.forEach(l=>{const li=h('li'),a=h('span','address',l.href),st=h('span','muted',' — '+x('Проверяем по базам угроз…'));li.append(a,st);linkUl.append(li);rep.set(l,st)});
  const draw=()=>{const nodes=[meter,h('p','muted',x('Оценка риска: {0} из 100',r.s)),h('p','',A[level])];
    if(reasons.length){nodes.push(h('h4','',x('Что насторожило:')),ul(reasons))}
    if(r.lk.length){nodes.push(h('h4','',x('Ссылки в сообщении:')),linkUl)}paint(o,level,T[level],nodes)};
  draw();o.focus();
  for(const l of r.lk){const res=await api('/api/url',{url:l.href});if(o._s!==seq)return;const rp=repOf(res);rep.get(l).textContent=' — '+rp.L.join(' ');
    if(rp.threat&&level!=='high'){level='high';reasons=[x('Ссылка из сообщения числится в базах угроз.'),...reasons];draw()}}
  logCheck('sms',level,r.s+'/100')});

/* ---- номер телефона ---- */
const CC={'1':'США или Канада','44':'Великобритания','49':'Германия','90':'Турция','91':'Индия','86':'Китай','971':'ОАЭ','998':'Узбекистан','996':'Кыргызстан','375':'Беларусь','380':'Украина','994':'Азербайджан','995':'Грузия','374':'Армения','992':'Таджикистан','48':'Польша'};
const CATS={bank:'Звонок от «банка» или «полиции»',invest:'Инвестиции или быстрый заработок',prize:'Приз, выигрыш, компенсация',family:'Родственник «попал в беду»',spam:'Спам или робозвонки',other:'Другое'};
function parsePhone(raw){
  let s=raw.trim().replace(/[\s().-]/g,'');if(s.startsWith('00'))s='+'+s.slice(2);
  if(!/^\+?\d{3,15}$/.test(s))return null;
  if(!s.startsWith('+')&&s.length<=6)return{kind:'short',d:s};
  let d=s.replace('+','');
  if(!s.startsWith('+')){if(d.length===11&&d[0]==='8')d='7'+d.slice(1);else if(d.length===10&&/^[67]/.test(d))d='7'+d}
  if(d.length<7||d.length>15)return null;
  if(d[0]==='7'){if(d.length!==11)return null;const a=d.slice(1,4);
    if(a==='800')return{kind:'toll',d};
    if(a[0]==='7')return a[1]==='1'||a[1]==='2'?{kind:'kzcity',d,code:a}:{kind:'kzmob',d};
    if(a[0]==='6')return{kind:'kz',d};
    return{kind:'ru',d}}
  const cc=[3,2,1].map(n=>d.slice(0,n)).find(c=>CC[c]);return{kind:'intl',d,country:cc?CC[cc]:null}}
const fmtPhone=p=>p.kind==='short'?p.d:p.d[0]==='7'&&p.d.length===11?`+7 ${p.d.slice(1,4)} ${p.d.slice(4,7)} ${p.d.slice(7,9)} ${p.d.slice(9)}`:'+'+p.d;
let lastPhone=null;
const pf=$('phoneForm');
if(pf){
  pf.addEventListener('submit',async e=>{e.preventDefault();
    const o=$('phoneResult'),rf=$('reportForm'),v=$('phoneInput').value;
    if(!v.trim())return show(o,'medium',x('Введите номер телефона.'),'');
    const p=parsePhone(v);
    if(!p){rf.hidden=true;return show(o,'medium',x('Номер не распознан'),'<p>'+x('Не удалось распознать номер. Введите его в международном формате, например +7 700 123 45 67.')+'</p>')}
    clearResult(o);const seq=o._s,F=[];let foreign=false;
    const type={kzmob:x('мобильный номер Казахстана'),kzcity:x('городской номер Казахстана (код {0})',p.code),kz:x('номер Казахстана'),toll:x('бесплатный номер 8-800'),short:x('короткий сервисный номер'),ru:x('мобильный или городской номер России'),intl:x('международный номер')}[p.kind];
    const country=p.kind==='ru'?x('Россия'):p.kind==='intl'?(p.country?x(p.country):x('неизвестный регион')):p.kind==='short'?null:x('Казахстан');
    if(p.kind==='ru'){foreign=true;F.push(x('Код +7 используют и Казахстан, и Россия: этот номер относится к российским кодам.'),x('Номер не казахстанский. Если звонящий представляется казахстанским банком или госорганом, это повод насторожиться.'))}
    if(p.kind==='intl'){foreign=true;F.push(x('Номер не казахстанский. Если звонящий представляется казахстанским банком или госорганом, это повод насторожиться.'))}
    if(p.kind==='short')F.push(x('Короткие номера могут быть платными: уточните стоимость у оператора.'));
    if(p.kind==='toll')F.push(x('Номера 8-800 бесплатны для звонящего, но сами по себе подлинность организации не подтверждают.'));
    if(/^kz/.test(p.kind))F.push(x('Формат казахстанского номера корректен. Это не означает, что звонящий тот, за кого себя выдаёт.'));
    const render=lk=>{let count=0,rep=[],cats=null;
      if(lk&&lk.ok){count=lk.data.count||0;cats=lk.data.categories||{};rep.push(count?x('Жалоб пользователей на этот номер: {0}.',count):x('Жалоб на этот номер в базе проекта пока нет. Это не значит, что номер безопасен.'));
        if(count)rep.push(x('Категории жалоб:')+' '+Object.entries(cats).map(([k,n])=>x(CATS[k]||'Другое')+' ('+n+')').join('; '))}
      else if(lk===null||(lk&&!lk.ok))rep.push(x('База жалоб недоступна: сервер не запущен.'));
      const level=count>=3?'high':(count>=1||foreign)?'medium':'info';
      const title=count>=3?x('Номер часто упоминается в жалобах'):level==='medium'?x('Номер требует осторожности'):x('Явных проблем не найдено');
      const pn=h('p');pn.append(h('strong','',x('Номер:')+' '),h('span','address',fmtPhone(p)));
      const pc=country?h('p','',x('Страна или регион:')+' '+country+'. '+x('Тип:')+' '+type+'.'):h('p','',x('Тип:')+' '+type+'.');
      paint(o,level,title,[pn,pc,ul(F.concat(rep)),h('p','disclaimer',x('Мошенники умеют подменять номера. Не доверяйте звонку только потому, что номер выглядит знакомым или официальным: перезвоните по номеру с официального сайта.'))])};
    render(undefined);o.focus();
    if(p.kind==='short'){rf.hidden=true;lastPhone=null;return}
    lastPhone='+'+p.d;rf.hidden=false;
    const lk=await api('/api/phone/lookup',{phone:lastPhone});if(o._s!==seq)return;const cnt=lk&&lk.ok?lk.data.count||0:0;render(lk);
    logCheck('phone',cnt>=3?'high':(cnt>=1||foreign)?'medium':'low','+'+p.d.slice(0,4)+' *** ** '+p.d.slice(-2))});
  $('reportForm').addEventListener('submit',async e=>{e.preventDefault();const msg=$('reportMsg');
    if(!lastPhone){msg.textContent=x('Сначала проверьте номер.');return}
    const r=await api('/api/phone/report',{phone:lastPhone,category:$('reportCategory').value});
    if(r&&r.ok){msg.textContent=x('Спасибо! Жалоба записана.');pf.dispatchEvent(new Event('submit',{cancelable:true}))}
    else if(r&&r.status===409)msg.textContent=x('Вы уже сообщали об этом номере сегодня.');
    else msg.textContent=x('Не удалось отправить жалобу. Проверьте, что сервер запущен.')});
}

/* ---- IP ---- */
function ipv4(v){const p=v.trim().split('.');if(p.length!==4||p.some(v=>!/^[0-9]{1,3}$/.test(v)))return null;const n=p.map(Number);return n.some(v=>v>255)?null:n}
const ipf=$('ipForm');
if(ipf)ipf.addEventListener('submit',e=>{e.preventDefault();
  const v=$('ipInput').value.trim(),o=$('ipResult'),ip=ipv4(v);
  if(!ip)return show(o,'medium',m('ipBadT'),'<p>'+m('ipBadP')+'</p>');
  const [a,b,c]=ip,f=[];
  if(a===10||(a===172&&b>=16&&b<=31)||(a===192&&b===168))f.push(m('ipPriv'));
  if(a===127)f.push(m('ipLoop'));
  if(a===169&&b===254)f.push(m('ipLink'));
  if(a===0||a>=224)f.push(m('ipSpec'));
  if((a===192&&b===0&&c===2)||(a===198&&b===51&&c===100)||(a===203&&b===0&&c===113))f.push(m('ipDoc'));
  logCheck('ip',f.length?'medium':'low',ip.join('.'));
  show(o,'info',f.length?m('ipSpecT'):m('ipOkT'),'<p><strong>'+m('ipLbl')+'</strong> '+ip.join('.')+'</p>'+(f.length?list(f):'<p>'+m('ipNone')+'</p>')+'<p>'+m('ipEnd')+'</p>')});

