  const say=(id,t)=>{$(id).textContent=t};
  $('profForm').addEventListener('submit',async e=>{e.preventDefault();const r=await api('/api/me/update',{name:$('pName').value});if(r&&r.ok){me.name=$('pName').value.trim();renderAcc();dashRender();say('profMsg',x('Сохранено.'))}else say('profMsg',errText(r))});
