  $('delForm').addEventListener('submit',async e=>{e.preventDefault();if(!confirm(x('Удалить аккаунт без возможности восстановления?')))return;const r=await api('/api/me/delete',{password:$('delPass').value});if(r&&r.ok){try{localStorage.removeItem('cs-academy');localStorage.removeItem('cs-checkup')}catch(err){}location.href='index.html'}else say('delMsg',r&&r.status===401?x('Неверный пароль.'):errText(r))});
  $('logoutBtn').addEventListener('click',async()=>{await api('/api/auth/logout',{});location.href='account.html'});
