/* ======================= пароль ======================= */
const COMMON=['password','123456','12345678','123456789','qwerty','qwerty123','111111','000000','abc123','iloveyou','admin','welcome','monkey','dragon','letmein','1q2w3e4r','1qaz2wsx','qazwsx','zaq12wsx','asdfgh','zxcvbn','qwertyuiop','password1','passw0rd','p@ssw0rd','12345','1234','777777','999999','kazakhstan','almaty','astana','qazaqstan','salem','123123','321321','654321','1q2w3e','q1w2e3','admin123','login','master','sunshine','princess','football','shadow','superman','qwe123','asdasd','zxcvbnm','1234567','12341234','пароль','привет','йцукен','qazaq','nazerke'];
function analyzePw(p){const issues=[],low=p.toLowerCase();let pool=0;
  if(/[a-z]/.test(p))pool+=26;if(/[A-Z]/.test(p))pool+=26;if(/\d/.test(p))pool+=10;if(/[^A-Za-z0-9а-яёәғқңөұүһі]/i.test(p))pool+=33;if(/[а-яёәғқңөұүһі]/i.test(p))pool+=33;
  let bits=p.length*Math.log2(pool||2);
  if(COMMON.includes(low)){issues.push('Это один из самых популярных паролей.');bits=Math.min(bits,10)}
  else{const w=COMMON.find(c=>c.length>=5&&low.includes(c));if(w){issues.push('Содержит популярное слово или комбинацию.');bits+=12-w.length*Math.log2(pool||2)}}
  if(/(.)\1{2,}/.test(p)){issues.push('Много повторяющихся символов подряд.');bits-=p.length*0.8}
  if(/(0123|1234|2345|3456|4567|5678|6789|abcd|bcde|qwer|asdf|zxcv|йцук)/i.test(p)){issues.push('Есть простая последовательность (1234, qwer).');bits-=8}
  if(/(19|20)\d{2}/.test(p)){issues.push('Содержит год: его легко угадать.');bits+=7-4*Math.log2(pool||2)}
  if(/^\d+$/.test(p))issues.push('Только цифры.');
  if(p.length<8)issues.push('Слишком короткий: нужно 12 символов и больше.');else if(p.length<12)issues.push('Лучше сделать длиннее: 12 символов и больше.');
  bits=Math.max(0,bits);return{bits,issues,score:bits<28?0:bits<36?1:bits<60?2:bits<80?3:4}}
const pwLabel=s=>x(['Очень слабый','Слабый','Средний','Хороший','Отличный'][s]);
function crackTime(bits){const s=Math.pow(2,bits)/1e10;
  if(s<1)return x('меньше секунды');if(s<60)return x('{0} сек.',Math.round(s));if(s<3600)return x('{0} мин.',Math.round(s/60));if(s<86400)return x('{0} ч.',Math.round(s/3600));
  if(s<31536000)return x('{0} дн.',Math.round(s/86400));const y=s/31536000;if(y<1000)return x('{0} лет',Math.round(y));if(y<1e6)return x('тысячи лет');return x('миллионы лет и больше')}
async function sha1Hex(str){if(!(window.crypto&&crypto.subtle))return null;const d=await crypto.subtle.digest('SHA-1',new TextEncoder().encode(str));return[...new Uint8Array(d)].map(b=>b.toString(16).padStart(2,'0')).join('').toUpperCase()}
async function pwned(p){try{const hx=await sha1Hex(p);if(!hx)return null;const r=await fetch('https://api.pwnedpasswords.com/range/'+hx.slice(0,5),{headers:{'Add-Padding':'true'}});if(!r.ok)return null;
  for(const l of (await r.text()).split('\n')){const [s,c]=l.trim().split(':');if(s===hx.slice(5))return +c||0}return 0}catch(e){return null}}
const pwf=$('pwForm');
if(pwf){
  $('pwToggle').addEventListener('click',e=>{const i=$('pwInput'),show=i.type==='password';i.type=show?'text':'password';e.target.textContent=x(show?'Скрыть':'Показать')});
  hooks.push(()=>{$('pwToggle').textContent=x($('pwInput').type==='password'?'Показать':'Скрыть')});
  pwf.addEventListener('submit',async e=>{e.preventDefault();const o=$('pwResult'),p=$('pwInput').value;if(!p)return show(o,'medium',x('Введите пароль.'),'');
    const a=analyzePw(p);clearResult(o);const seq=o._s,hb=$('pwHibp').checked;
    const meter=h('div','meter');const bar=h('span');bar.style.width=(a.score+1)*20+'%';meter.append(bar);
    const draw=pw=>{const lvl=pw>0||a.score<=1?'high':a.score===2?'medium':'low',nodes=[meter,h('p','',x('Надёжность: {0}',pwLabel(a.score))+'. '+x('Оценочное время подбора: {0}.',crackTime(a.bits)))];
      if(a.issues.length)nodes.push(ul(a.issues.map(i=>x(i))));
      if(hb)nodes.push(h('p','',pw===undefined?x('Проверяем по базе утечек…'):pw===null?x('Не удалось проверить базу утечек: нет доступа к сервису или к защищённому режиму браузера.'):pw>0?x('Этот пароль найден в утечках ({0} раз). Не используйте его.',pw):x('В известных утечках этот пароль не найден. Это не гарантия надёжности.')));
      nodes.push(h('p','disclaimer',x('Придумайте длинную фразу из нескольких слов и используйте её только для одного аккаунта.')));
      paint(o,lvl,pwLabel(a.score),nodes);return lvl};
    draw(hb?undefined:0);o.focus();let pw=0;if(hb){pw=await pwned(p);if(o._s!==seq)return}
    const lvl=draw(pw);logCheck('password',lvl,a.score+'/4')});
}

/* ======================= QR-код ======================= */
let qrStream=null,qrTimer=null;
function loadQr(){return window.CSQR?Promise.resolve():new Promise((ok,no)=>{const s=document.createElement('script');s.src='qr.js?v=4';s.onload=ok;s.onerror=no;document.head.append(s)})}
async function decodeCanvas(cv){
  if('BarcodeDetector' in window){try{const r=await new BarcodeDetector({formats:['qr_code']}).detect(cv);if(r.length&&r[0].rawValue)return r[0].rawValue}catch(e){}}
  try{await loadQr()}catch(e){return null}
  return CSQR.decode(cv.getContext('2d').getImageData(0,0,cv.width,cv.height))}
function qrStop(){clearInterval(qrTimer);if(qrStream){qrStream.getTracks().forEach(t=>t.stop());qrStream=null}const v=$('qrView');if(v)v.hidden=true}
async function qrFromImage(f){
  const url=URL.createObjectURL(f),img=new Image();await new Promise((ok,no)=>{img.onload=ok;img.onerror=no;img.src=url}).finally(()=>URL.revokeObjectURL(url));
  for(const mx of [1000,640,400]){const sc=Math.min(1,mx/Math.max(img.width,img.height)),cv=h('canvas');cv.width=Math.round(img.width*sc);cv.height=Math.round(img.height*sc);cv.getContext('2d',{willReadFrequently:true}).drawImage(img,0,0,cv.width,cv.height);const t=await decodeCanvas(cv);if(t)return t}
  return null}
const WIFI=/^WIFI:/i;
async function handleQr(text){
  const o=$('qrResult'),t=text.trim();clearResult(o);
  if(/^https?:\/\//i.test(t)||(/^(www\.)?[a-z0-9-]+(\.[a-z0-9-]+)+(\/\S*)?$/i.test(t)))return runUrl(t,o,'qr');
  const pre=h('pre','qrtext',t.slice(0,600));let level='medium',title,tag='text',notes=[];
  if(WIFI.test(t)){const m=/S:([^;]*)/i.exec(t);title=x('QR-код с настройками Wi-Fi');tag='Wi-Fi';notes.push(x('Сеть: {0}. Подключайтесь только к сетям, которым доверяете.',m?m[1]:'?'))}
  else if(/^(tel:|sms:|smsto:|mailto:)/i.test(t)){title=x('QR-код запускает действие');tag=t.split(':')[0].toLowerCase()+':';notes.push(x('После сканирования телефон может позвонить, отправить SMS или письмо. Проверьте номер или адрес.'))}
  else if(/^(bitcoin|ethereum|litecoin|monero|tron):/i.test(t)){title=x('QR-код для платежа');tag='payment';notes.push(x('Это адрес для перевода денег. Переводы в криптовалюте нельзя вернуть.'))}
  else if(/^otpauth:/i.test(t)){title=x('Ключ двухфакторной защиты');tag='otpauth';notes.push(x('Этот код даёт доступ к вашим одноразовым паролям. Никому его не показывайте.'))}
  else if(/^BEGIN:VCARD/i.test(t)){level='low';tag='vCard';title=x('Визитка с контактами');notes.push(x('Проверьте данные перед сохранением в контакты.'))}
  else{const r=scoreSms(t);level=r.level==='info'?'low':r.level;title=level==='high'?x('Высокая вероятность мошенничества'):level==='medium'?x('Есть тревожные признаки'):x('Обычный текст');notes=r.R}
  paint(o,level,title,[h('p','',x('Содержимое QR-кода:')),pre,...(notes.length?[ul(notes)]:[]),h('p','disclaimer',x('Мы ничего не открывали и не отправляли.'))]);o.focus();logCheck('qr',level,tag)}
const qrCam=$('qrCam');
if(qrCam){
  const msg=t=>{const o=$('qrResult');show(o,'medium',x('QR-код не распознан'),'<p>'+t+'</p>')};
  qrCam.addEventListener('click',async()=>{
    if(!(navigator.mediaDevices&&navigator.mediaDevices.getUserMedia))return msg(x('Камера доступна только на защищённых страницах (https) или на localhost. Загрузите изображение с QR-кодом.'));
    try{qrStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false})}catch(e){return msg(x('Нет доступа к камере. Разрешите её в настройках браузера или загрузите изображение.'))}
    const v=$('qrVideo');v.srcObject=qrStream;await v.play();$('qrView').hidden=false;clearResult($('qrResult'));
    const cv=h('canvas'),ctx=cv.getContext('2d',{willReadFrequently:true});let busy=false;
    qrTimer=setInterval(async()=>{if(busy||!v.videoWidth)return;busy=true;const sc=Math.min(1,720/v.videoWidth);cv.width=Math.round(v.videoWidth*sc);cv.height=Math.round(v.videoHeight*sc);ctx.drawImage(v,0,0,cv.width,cv.height);
      const t=await decodeCanvas(cv);busy=false;if(t){qrStop();handleQr(t)}},350)});
  $('qrStop').addEventListener('click',qrStop);
  $('qrFile').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;qrStop();
    let t=null;try{t=await qrFromImage(f)}catch(err){}
    if(t)handleQr(t);else msg(x('Не удалось найти QR-код на изображении. Сделайте снимок ближе и ровнее, чтобы код занимал большую часть кадра.'))});
  hooks.push(qrStop);
}

/* ======================= файл ======================= */
function sha256js(m){const P=[];for(let n=2;P.length<64;n++)if(P.every(p=>n%p))P.push(n);
  const fr=v=>Math.floor((v%1)*4294967296),K=P.map(p=>fr(Math.cbrt(p))),H=P.slice(0,8).map(p=>fr(Math.sqrt(p)));
  const l=m.length,nb=((l+9+63)>>6)<<6,b=new Uint8Array(nb);b.set(m);b[l]=128;const dv=new DataView(b.buffer);dv.setUint32(nb-4,(l*8)>>>0);dv.setUint32(nb-8,Math.floor(l/536870912));
  const w=new Uint32Array(64),rr=(v,n)=>(v>>>n)|(v<<(32-n));
  for(let i=0;i<nb;i+=64){for(let t=0;t<16;t++)w[t]=dv.getUint32(i+t*4);
    for(let t=16;t<64;t++){const s0=rr(w[t-15],7)^rr(w[t-15],18)^(w[t-15]>>>3),s1=rr(w[t-2],17)^rr(w[t-2],19)^(w[t-2]>>>10);w[t]=(w[t-16]+s0+w[t-7]+s1)>>>0}
    let [a,bb,c,d,e,f,g,hh]=H;
    for(let t=0;t<64;t++){const S1=rr(e,6)^rr(e,11)^rr(e,25),ch=(e&f)^(~e&g),t1=(hh+S1+ch+K[t]+w[t])>>>0,S0=rr(a,2)^rr(a,13)^rr(a,22),mj=(a&bb)^(a&c)^(bb&c),t2=(S0+mj)>>>0;hh=g;g=f;f=e;e=(d+t1)>>>0;d=c;c=bb;bb=a;a=(t1+t2)>>>0}
    [a,bb,c,d,e,f,g,hh].forEach((v,k)=>{H[k]=(H[k]+v)>>>0})}
  return H.map(v=>v.toString(16).padStart(8,'0')).join('')}
async function sha256Hex(buf){if(window.crypto&&crypto.subtle){try{return[...new Uint8Array(await crypto.subtle.digest('SHA-256',buf))].map(b=>b.toString(16).padStart(2,'0')).join('')}catch(e){}}return sha256js(new Uint8Array(buf))}
const EXEC_EXT=new Set(['exe','msi','scr','bat','cmd','com','pif','vbs','vbe','js','jse','wsf','ps1','jar','apk','xapk','lnk','dll','reg','hta','cpl','msc','app','dmg','pkg','sh','deb','rpm']);
const MACRO_EXT=new Set(['docm','xlsm','pptm','dotm','xlsb','xlam']),ARCH_EXT=new Set(['zip','rar','7z','tar','gz','iso','img']);
function sniff(u){const s=n=>String.fromCharCode(...u.subarray(0,n));
  if(u[0]===0x4d&&u[1]===0x5a)return'exe';if(u[0]===0x7f&&s(4).slice(1)==='ELF')return'elf';if((u[0]===0xcf||u[0]===0xce)&&u[1]===0xfa&&u[2]===0xed&&u[3]===0xfe)return'macho';
  if(s(4)==='%PDF')return'pdf';if(u[0]===0x50&&u[1]===0x4b&&(u[2]===3||u[2]===5))return'zip';if(u[0]===0xd0&&u[1]===0xcf&&u[2]===0x11&&u[3]===0xe0)return'ole';
  if(s(4)==='Rar!')return'rar';if(u[0]===0x37&&u[1]===0x7a&&u[2]===0xbc&&u[3]===0xaf)return'7z';if(u[0]===0xff&&u[1]===0xd8)return'jpg';if(u[0]===0x89&&s(4).slice(1)==='PNG')return'png';if(s(3)==='GIF')return'gif';if(s(5)==='{\\rtf')return'rtf';return''}
const OKMAGIC={pdf:['pdf'],jpg:['jpg'],jpeg:['jpg'],png:['png'],gif:['gif'],doc:['ole','zip','rtf'],xls:['ole','zip'],ppt:['ole','zip'],docx:['zip'],xlsx:['zip'],pptx:['zip'],odt:['zip'],zip:['zip'],rar:['rar'],'7z':['7z'],apk:['zip'],jar:['zip'],exe:['exe'],dll:['exe']};
function zipInfo(u){const dv=new DataView(u.buffer,u.byteOffset,u.byteLength);let e=-1;for(let i=u.length-22;i>=Math.max(0,u.length-65558);i--){if(dv.getUint32(i,true)===0x06054b50){e=i;break}}if(e<0)return null;
  const n=dv.getUint16(e+10,true);let p=dv.getUint32(e+16,true);const names=[];let enc=false;
  for(let k=0;k<n&&p+46<=u.length&&names.length<3000;k++){if(dv.getUint32(p,true)!==0x02014b50)break;const fl=dv.getUint16(p+8,true),nl=dv.getUint16(p+28,true),xl=dv.getUint16(p+30,true),cl=dv.getUint16(p+32,true);if(fl&1)enc=true;names.push(new TextDecoder().decode(u.subarray(p+46,p+46+nl)).toLowerCase());p+=46+nl+xl+cl}
  return{names,enc}}
function hasBytes(u,pat,lim){const n=Math.min(u.length,lim||10485760)-pat.length;for(let i=0;i<=n;i++){if(u[i]!==pat[0])continue;let j=1;while(j<pat.length&&u[i+j]===pat[j])j++;if(j===pat.length)return true}return false}
const rank={low:0,medium:1,high:2};
async function runFile(file){
  const o=$('fileResult');clearResult(o);const seq=o._s;
  if(file.size>50*1048576)return show(o,'medium',x('Файл слишком большой'),'<p>'+x('Для проверки в браузере файл должен быть не больше 50 МБ.')+'</p>');
  const nodes0=[h('p','muted',x('Считаем отпечаток и анализируем файл…'))];paint(o,'info',x('Проверка файла'),nodes0);o.focus();
  const buf=await file.arrayBuffer(),u=new Uint8Array(buf),sha=await sha256Hex(buf);if(o._s!==seq)return;
  const name=file.name,ext=(name.split('.').pop()||'').toLowerCase(),F=[];let level='low';
  const add=(lv,t)=>{F.push(t);if(rank[lv]>rank[level])level=lv};
  const kind=sniff(u);
  if(/[\u202e\u202d]/.test(name))add('high',x('В имени файла есть скрытый символ, который переворачивает расширение: так маскируют программы под документы.'));
  if(/\.(pdf|docx?|xlsx?|pptx?|jpe?g|png|gif|txt|mp[34]|zip|rar)\.(exe|scr|bat|cmd|js|vbs|lnk|apk|com|jar)$/i.test(name))add('high',x('Двойное расширение: файл выглядит как документ, но является программой.'));
  else if(EXEC_EXT.has(ext))add('medium',x('Это исполняемый файл или установщик (.{0}). Запускайте только то, что получили из надёжного источника.',ext));
  if(MACRO_EXT.has(ext))add('medium',x('Документ с макросами. Мошенники часто прячут в них вредоносный код: не включайте макросы.'));
  if(['exe','elf','macho'].includes(kind)&&!EXEC_EXT.has(ext)&&!OKMAGIC[ext]?.includes(kind))add('high',x('Внутри файла находится программа, хотя расширение .{0} это скрывает.',ext||'—'));
  else if(OKMAGIC[ext]&&kind&&!OKMAGIC[ext].includes(kind)&&!['exe','elf','macho'].includes(kind))add('medium',x('Содержимое файла не совпадает с его расширением (.{0}).',ext));
  if(kind==='zip'){const z=zipInfo(u);
    if(z){const nm=z.names;
      if(nm.some(n=>n.endsWith('vbaproject.bin')))add(['docx','xlsx','pptx'].includes(ext)?'high':'medium',x('Внутри есть макросы (VBA).'));
      if(nm.includes('androidmanifest.xml')&&nm.some(n=>n.endsWith('.dex')))add(ext==='apk'?'medium':'high',x('Это установочный файл Android-приложения (APK). Устанавливайте приложения только из Google Play.'));
      const ex=nm.find(n=>/\.(exe|scr|bat|cmd|js|vbs|lnk|msi|jar|ps1)$/.test(n));if(ex&&!['jar','apk'].includes(ext))add('medium',x('В архиве есть исполняемый файл: {0}.',ex.slice(-40)));
      if(z.enc)add('medium',x('Архив защищён паролем: его содержимое нельзя проверить. Так часто обходят антивирусы.'))}}
  if(kind==='ole'&&['doc','xls','ppt'].includes(ext)&&(hasBytes(u,[86,0,66,0,65,0])||hasBytes(u,[77,0,97,0,99,0,114,0,111,0,115])))add('medium',x('Похоже, внутри есть макросы. Не включайте их, если не уверены в источнике.'));
  if(kind==='pdf'){const t=new TextDecoder('latin1').decode(u.subarray(0,Math.min(u.length,4194304)));
    if(/\/Launch/.test(t))add('high',x('PDF пытается запускать внешние программы (/Launch).'));
    if(/\/JavaScript|\/JS\b|\/OpenAction|\/EmbeddedFile/.test(t))add('medium',x('PDF содержит скрипты или вложенные файлы. Обычные документы редко их используют.'))}
  if(ARCH_EXT.has(ext)&&!F.length)F.push(x('Архив: проверьте его содержимое перед распаковкой.'));
  const sh=h('p');sh.append(h('strong','',x('Отпечаток SHA-256:')+' '),h('code','address',sha));
  const info=h('p','',x('Файл:')+' '+name+' ('+(file.size<1048576?Math.max(1,Math.round(file.size/1024))+' '+x('КБ'):(file.size/1048576).toFixed(1)+' '+x('МБ'))+')');
  const draw=(rp,lv)=>{const title=lv==='high'?x('Файл выглядит опасным'):lv==='medium'?x('Файл требует осторожности'):x('Явных признаков опасности не найдено');
    const nodes=[info,sh];if(F.length)nodes.push(ul(F));else nodes.push(h('p','',x('Простые проверки не нашли подозрительных признаков. Это не гарантия: опасные файлы могут выглядеть обычно.')));
    nodes.push(rp?(rp.L.length?ul(rp.L):h('p')):h('p','muted',x('Сверяем отпечаток с базой VirusTotal…')));
    nodes.push(h('p','disclaimer',x('Файл не загружался на сервер: сверка идёт только по его отпечатку.')));paint(o,lv,title,nodes)};
  draw(null,level);
  const res=await api('/api/file',{sha256:sha});if(o._s!==seq)return;
  const L=[];if(res&&res.status===429)L.push(x('Слишком много проверок подряд. Повторите через минуту.'));
  else if(!res||!res.ok)L.push(x('Онлайн-сверка с базами угроз недоступна.'));
  else{const d=res.data;
    if(d.status==='threat'){L.push(x('VirusTotal: {0} из {1} движков считают файл вредоносным или подозрительным.',d.flagged,d.total)+(d.label?' ('+d.label+')':''));level='high'}
    else if(d.status==='clean')L.push(x('VirusTotal: файл известен, вредоносным не признан ({0} движков проверили).',d.total));
    else if(d.status==='unknown')L.push(x('VirusTotal: такого файла в базе нет. Это не значит, что он безопасен.'));
    else if(d.status==='off')L.push(x('VirusTotal: не подключён на сервере.'));else L.push(x('VirusTotal: не удалось получить ответ (возможен лимит запросов).'))}
  draw({L},level);logCheck('file',level,name.slice(-60))}
const fileIn=$('fileInput');
if(fileIn){
  fileIn.addEventListener('change',e=>{const f=e.target.files[0];e.target.value='';if(f)runFile(f)});
  const dz=$('fileDrop');['dragover','dragenter'].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.add('over')}));['dragleave','drop'].forEach(ev=>dz.addEventListener(ev,()=>dz.classList.remove('over')));
  dz.addEventListener('drop',e=>{e.preventDefault();const f=e.dataTransfer.files[0];if(f)runFile(f)});
}

